theorem extracted_1.{u_10, u_9, u_8} {G : Type u_8} [hG : MeasurableSpace G] [inst : AddCommGroup G]
  [inst_1 : MeasurableSingletonClass G] [inst_2 : Countable G] {m : ℕ} {Ω : Type u_9} [hΩ : MeasureSpace Ω]
  {S : Type u_10} [hS : MeasurableSpace S] [inst_3 : MeasurableSingletonClass S] {X : Fin m → Ω → G}
  (hX : ∀ (i : Fin m), Measurable (X i)) {Y : Fin m → Ω → S} (hY : ∀ (i : Fin m), Measurable (Y i))
  (h_indep : iIndepFun (fun x => hG.prod hS) (fun i => ⟨X i, Y i⟩) ℙ) (this : IsProbabilityMeasure ℙ) :
  let E := fun i yi => Y i ⁻¹' {yi};
  let E' := fun y => ⋂ i, E i (y i);
  let f := fun y => ∏ i : Fin m, (ℙ (E i (y i))).toReal;
  ∀ (i : Fin m) (y : Fin m → S), ¬f y = 0 → f y * H[X i ; ℙ[|E' y]] = f y * H[X i ; ℙ[|E i (y i)]] := by
  simp only [hf, zero_mul]

theorem extracted_1.{u_10, u_9, u_8} {G : Type u_8} {H : Type u_9} [hG : MeasurableSpace G]
  [inst : MeasurableSingletonClass G] [inst_1 : AddCommGroup G] [hH : MeasurableSpace H]
  [inst_2 : MeasurableSingletonClass H] [inst_3 : AddCommGroup H] (π : G →+ H) {m : ℕ} {Ω : Type u_10}
  (hΩ : MeasureSpace Ω) {X : Fin m → Ω → G} (hmes : ∀ (i : Fin m), Measurable (X i))
  (h_indep : iIndepFun (fun x => hG) X ℙ) (this : IsProbabilityMeasure ℙ) :
  let S := ∑ i : Fin m, X i;
  let piX := fun ω i => π (X i ω);
  Measurable S → Measurable piX → I[S : piX|⇑π ∘ S] = H[S | ⇑π ∘ S] + H[piX | ⇑π ∘ S] - H[⟨S, piX⟩ | ⇑π ∘ S] := by
  condMutualInfo_eq hSmes hpiXmes (Measurable.comp .of_discrete hSmes)]

theorem extracted_1.{u_10, u_8} {G : Type u_8} [hG : MeasurableSpace G] [inst : MeasurableSingletonClass G]
  [inst_1 : AddCommGroup G] {m : ℕ} {Ω : Type u_10} (hΩ : MeasureSpace Ω) {X : Fin m → Ω → G}
  (hmes : ∀ (i : Fin m), Measurable (X i)) (h_indep : iIndepFun (fun x => hG) X ℙ) (this : IsProbabilityMeasure ℙ) :
  let S := ∑ i : Fin m, X i;
  Measurable S := by
  fun_prop

theorem extracted_1.{u_9, u_8} {m : ℕ} (hm : m > 0) {G : Fin (m + 1) → Type u_8}
  [hG : (i : Fin (m + 1)) → MeasurableSpace (G i)] [hGs : ∀ (i : Fin (m + 1)), MeasurableSingletonClass (G i)]
  [hGa : (i : Fin (m + 1)) → AddCommGroup (G i)] {φ : (i : Fin m) → G i.succ →+ G i.castSucc}
  {π : (d : Fin (m + 1)) → G ↑m →+ G d} (hπ0 : π 0 = 0) (hcomp : ∀ (i : Fin m), ⇑(π i.castSucc) = ⇑(φ i) ∘ ⇑(π i.succ))
  {Ω : Type u_9} [hΩ : MeasureSpace Ω] {X : Fin m → Ω → G ↑m} (hX : ∀ (i : Fin m), Measurable (X i))
  (h_indep : iIndepFun (fun x => hG ↑m) X ℙ) (this_1 : IsProbabilityMeasure ℙ) (this : NeZero m) :
  let f := fun i =>
    I[∑ i' : Fin m, X i' : fun ω i' =>
      (π i.succ) (X i' ω)|⟨⇑(π i.succ) ∘ ∑ i' : Fin m, X i', fun ω i' => (π ↑↑i) (X i' ω)⟩];
  (∀ (i : Fin m), 0 ≤ f i) →
    let F := fun x => (x, fun x => 0);
    Injective F → ∀ (a a' : Ω), a = a' → ∀ (a_1 a'_1 : Fin m), a_1 = a'_1 → 1 = Fin.succ 0 := by
  simp [Fin.succ_zero_eq_one']

